#include <vector>
#include <iostream>

int main() {
    std::vector<int> v = {1, 2, 3};

    // Shrinkage: Elements 3 destroyed
    v.resize(2);
    std::cout << "Size after shrink: " << v.size() << "\n"; // Output: 2

    // Growth (Default Construction if int had one, but int is zero-initialized)
    v.resize(5);
    std::cout << "Size after growth: " << v.size() << "\n"; // Output: 5

    // Growth (Copy Construction)
    v.resize(7, 99);

    // Vector iterator invalidation concern:
    // If resize(100) triggers reallocation, existing iterators become invalid.
}
